import { Component, Input, OnDestroy, OnInit } from '@angular/core';
import { UntypedFormArray, UntypedFormBuilder, UntypedFormGroup, ValidationErrors } from '@angular/forms';
import { DefaultFormBaseComponent } from '@polpware/ngx-form-common';
import { INgxLogger, LoggerProviderImpl } from '@polpware/ngx-logger';
import { Subscription } from 'rxjs';

function findFirstDuplicate(array: string[]) {
    var valuesSoFar: { [key: string]: boolean } = Object.create(null);
    for (let i = 0; i < array.length; ++i) {
        const value = array[i];
        if (value in valuesSoFar) {
            return value;
        }
        valuesSoFar[value] = true;
    }
    return '';
}

function makeFormValidator(targetColumns: Array<{
    label: string;
    id: string;
    required: boolean;
}>) {
    return (control: UntypedFormGroup): ValidationErrors | null => {
        // Make sure that
        const mappings = control.get('mappings') as UntypedFormArray;
        const subset = mappings.controls.filter((x: UntypedFormGroup) => {
            const checked = x.get('targetId');
            return !!checked.value;
        });
        const targetIds = subset.map((y: UntypedFormGroup) => {
            return y.get('targetId').value;
        });

        // Check redundancy
        const anyDuplicate = findFirstDuplicate(targetIds);
        if (anyDuplicate) {
            const desc = targetColumns.find(a => a.id == anyDuplicate);
            return {
                duplicate: `${desc?.label}(${desc?.id})`
            }
        }
        // Check if all required are included.
        const anyMissing = targetColumns
            .filter(a => a.required)
            .find(b => !targetIds.some(c => c == b.id));
        if (anyMissing) {
            return {
                missing: `${anyMissing.label}(${anyMissing.id})`
            }
        }

        return null;
    };
}


@Component({
    selector: 'polp-define-column-mapping',
    templateUrl: './define-column-mapping.component.html',
    styleUrls: ['./define-column-mapping.component.css']
})
export class DefineColumnMappingComponent extends DefaultFormBaseComponent
    implements OnInit, OnDestroy {

    @Input() sourceColumns: Array<{
        label: string;
        id: string;
    }> = [];
    @Input() targetColumns: Array<{
        label: string;
        id: string;
        required: boolean;
    }> = [];
    @Input() initValue: Array<{
        sourceId: string;
        targetId: string;
    }> = [];

    form: UntypedFormGroup;

    private _subr: Subscription;
    private readonly _logger: INgxLogger;

    constructor(private readonly _builder: UntypedFormBuilder,
        loggerProvider: LoggerProviderImpl) {
        super();

        this._logger = loggerProvider.logger('polp_data_transport_define_column_mapping');

    }

    get mappings() {
        return this.form.get('mappings') as UntypedFormArray;
    }

    ngOnInit(): void {
        // Build form
        this.form = this._builder.group({
            mappings: this._builder.array([])
        }, { validators: [makeFormValidator(this.targetColumns)] });

        this._subr = this.form.valueChanges.subscribe(a => {
            const b = a.mappings as Array<{ checked: boolean; sourceId: string; targetId: string }>;
            const c = b.filter(b => b.targetId);
            this.onValueChanged.emit(c);
            this.onValidation.emit(this.form.errors);
        });
        this.sourceColumns.forEach(source => {
            // Build mapping entries
            const record = {
                checked: false,
                sourceId: source.id,
                targetId: ''
            };

            const anyMap = this.initValue.find(x => x.sourceId == source.id);
            if (anyMap) {
                record.targetId = anyMap.targetId;
            }

            this.mappings.push(this._builder.group(record));
        });
    }

    ngOnDestroy() {
        this._subr && this._subr.unsubscribe();
    }

    sourceLabel(i: number) {
        const id = this.mappings.controls[i].value.sourceId;
        return this.sourceColumns.find(a => a.id == id).label;
    }

}
