import { Component, OnInit, Input } from '@angular/core';
import { ObservableModalAbstractComponent } from '@polpware/bs-components';
import { BsModalRef, BsModalService } from 'ngx-bootstrap/modal';
import { faSave } from '@fortawesome/free-solid-svg-icons';
import { NgxFileDropEntry } from 'ngx-file-drop';

// todo: Configuration 
export interface IModalInput {
    multiple?: boolean;
    accept?: string;
    maxFileSizeInBytes?: number; // byets
}

@Component({
    selector: 'polp-drop-file-modal',
    templateUrl: './drop-file-modal.component.html',
    styleUrls: ['./drop-file-modal.component.css']
})
export class DropFileModalComponent
    extends ObservableModalAbstractComponent<IModalInput, File[]>
    implements OnInit {

    faSave = faSave;

    items: File[] = [];
    valid: boolean = false;
    title = 'Select a file';

    @Input()
    multiple: boolean = false;
    @Input()
    accept: string = '*';
    @Input()
    maxFileSizeInBytes: number = undefined;

    constructor(
        public readonly bsModalRef: BsModalRef,
        protected readonly bsModalService: BsModalService
    ) {
        super();
    }

    ngOnInit(): void {
    }

    onSelect(files: NgxFileDropEntry[]) {
        for (const droppedFile of files) {
            // Is it a file?
            if (droppedFile.fileEntry.isFile) {
                const fileEntry = droppedFile.fileEntry as FileSystemFileEntry;
                fileEntry.file((file: File) => {
                    if (!this.maxFileSizeInBytes || (this.maxFileSizeInBytes && file.size < this.maxFileSizeInBytes)) {
                        this.items = [...this.items, file];
                    }
                });
            } else {
                // It was a directory (empty directories are added, otherwise only files)
            }
        }

        this.valid = this.items.length > 0;
    }

    onRemove(event: File) {
        this.items = this.items.filter(x => x != event);
        this.valid = this.items.length > 0;
    }

    confirm() {
        this.closeModal(this.items);
    }

    close() {
        this.closeModal(null);
    }

}
